#[derive(Default)]
struct MemStore {
    rows: Mutex<BTreeMap<(String, String), String>>,
}

#[async_trait]
impl SnapshotStore for MemStore {
    async fn scan(
        &self,
        pkey: &str,
        from: Option<&str>,
        to: Option<&str>,
        _limit: u32,
    ) -> anyhow::Result<Vec<(String, String)>> {
        Ok(self
            .rows
            .lock()
            .unwrap()
            .iter()
            .filter(|((p, l), _)| {
                p == pkey
                    && from.is_none_or(|f| l.as_str() >= f)
                    && to.is_none_or(|t| l.as_str() <= t)
            })
            .map(|((_, l), v)| (l.clone(), v.clone()))
            .collect())
    }

    async fn put_with_ttl(
        &self,
        pkey: &str,
        lkey: &str,
        value: String,
        _ttl_nanos: i64,
    ) -> anyhow::Result<()> {
        self.rows
            .lock()
            .unwrap()
            .insert((pkey.to_string(), lkey.to_string()), value);
        Ok(())
    }

    async fn delete(&self, pkey: &str, lkey: &str) -> anyhow::Result<()> {
        self.rows
            .lock()
            .unwrap()
            .remove(&(pkey.to_string(), lkey.to_string()));
        Ok(())
    }
}

